import{_ as a,a as s,c as i,b as n}from"./chunks/framework.b9WMfGr4.js";const u=JSON.parse('{"title":"01-核心定位与架构原则","description":"深入解析个人博客的系统定位、单分支开发模式、双仓库解耦流水线与自动化发布机制。","frontmatter":{"title":"01-核心定位与架构原则","date":"2026-10-01T00:00:00.000Z","author":"道林学长","description":"深入解析个人博客的系统定位、单分支开发模式、双仓库解耦流水线与自动化发布机制。","tags":["设计原则","架构设计"]},"headers":[],"relativePath":"posts/0-博客指南/博客的设计原则/01-核心定位与架构原则.md","filePath":"posts/0-博客指南/博客的设计原则/01-核心定位与架构原则.md"}'),t={name:"posts/0-博客指南/博客的设计原则/01-核心定位与架构原则.md"};function l(o,e,r,d,p,c){return s(),i("div",null,[...e[0]||(e[0]=[n(`<h1 class="hidden-duplicate-h1" style="display:none !important;" id="_01-核心定位与架构原则" tabindex="-1">01-核心定位与架构原则 <a class="header-anchor" href="#_01-核心定位与架构原则" aria-label="Permalink to &quot;01-核心定位与架构原则&quot;">​</a></h1><div class="post-cover-wrapper"><img src="https://images.unsplash.com/photo-1517694712202-14dd9538aa97?auto=format&amp;fit=crop&amp;w=1200&amp;q=80" alt="cover" class="post-cover-image" referrerpolicy="no-referrer" loading="lazy"></div><p>个人博客是知识结晶、技术思考与系统化沉淀的数字化载体。为了保持长期持续写作的低摩擦与高稳定性，系统在架构之初便确立了明确的技术定位与研发协同原则。</p><h2 id="_1-系统定位与核心诉求" tabindex="-1">1. 系统定位与核心诉求 <a class="header-anchor" href="#_1-系统定位与核心诉求" aria-label="Permalink to &quot;1. 系统定位与核心诉求&quot;">​</a></h2><p>在主流技术博客方案中，常见的选型往往在重量级动态系统如 WordPress、Ghost 与轻量级静态站点如 Hexo、Hugo、VitePress 之间权衡。</p><p>本博客选用 VitePress 作为核心引擎，深度结合 Vue 3 与 TypeScript，以满足技术博主的核心诉求：</p><ul><li><strong>极速响应与现代化技术栈</strong>：基于 Vite 原生 ESM 驱动，本地写作热更新即时生效，毫秒级响应极大提升撰写心境。</li><li><strong>完全掌控的源码定制空间</strong>：不依赖黑盒插件生态，全站布局、主题样式、交互组件均以单文件组件方式透明维护。</li><li><strong>纯静态产物与零服务端运维</strong>：编译产物全部为纯静态 HTML、CSS 与客户端水合脚本，天然免疫服务端注入风险，具备极致的托管稳定性与访问性能。</li></ul><h2 id="_2-工作战场单一化与单分支模式" tabindex="-1">2. 工作战场单一化与单分支模式 <a class="header-anchor" href="#_2-工作战场单一化与单分支模式" aria-label="Permalink to &quot;2. 工作战场单一化与单分支模式&quot;">​</a></h2><p>工程维护中最消耗心智的往往是复杂的分支管理策略。为了杜绝上下文切换内耗，博客确立了工作战场单一化原则：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><button class="collapse-btn" title="折叠代码" aria-label="折叠代码"><svg class="collapse-icon" viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg></button><span class="lang">Text</span><pre class="shiki shiki-themes github-light one-dark-pro vp-code" tabindex="0"><code><span class="line"><span>blog-source (私有主战场)</span></span>
<span class="line"><span>  └── main (唯一工作分支)</span></span>
<span class="line"><span>        ├── 系统配置文件 (.vitepress/config.ts)</span></span>
<span class="line"><span>        ├── 主题与交互组件 (.vitepress/theme/)</span></span>
<span class="line"><span>        ├── 静态页面 (pages/)</span></span>
<span class="line"><span>        └── 全站博文与指南 (posts/)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div><div class="code-collapsed-indicator"><span class="code-collapsed-text">已折叠代码，点击展开</span><svg class="expand-icon" viewBox="0 0 24 24" width="12" height="12" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"></polyline></svg></div></div><ul><li><strong>全资产纳管于单一仓库</strong>：所有博客源代码、主题配置、辅助脚本以及全部博文笔记，统一放置于私有源码仓库内。</li><li><strong>坚决贯彻单分支 main 模式</strong>：不拆分所谓代码开发分支与内容创作分支，杜绝在不同分支间来回切换带来的合并冲突或工作区脏状态。</li><li><strong>阶段性变更自动持久化</strong>：遵循版本历史不丢失原则，完成阶段性修改、功能开发或文档调整后，应主动完成 Git 提交，及时固化工作成果。</li></ul><h2 id="_3-双仓库流水线与安全发布" tabindex="-1">3. 双仓库流水线与安全发布 <a class="header-anchor" href="#_3-双仓库流水线与安全发布" aria-label="Permalink to &quot;3. 双仓库流水线与安全发布&quot;">​</a></h2><p>在代码资产保护与公开访问之间，博客构建了稳健的双仓库流水线解耦架构：</p><div class="interactive-diagram-card show-dynamic" data-type="mermaid" data-current-mode="dynamic" data-alt="" data-hash="fe35df2f"><div class="diagram-header"><div class="header-left"><span class="diagram-dots"></span><span class="diagram-type-tag">Mermaid</span></div><div class="header-actions"><div class="diagram-canvas-tools"><button class="tool-btn zoom-in" title="放大画布" aria-label="放大画布"><svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="8"></circle><line x1="21" y1="21" x2="16.65" y2="16.65"></line><line x1="11" y1="8" x2="11" y2="14"></line><line x1="8" y1="11" x2="14" y2="11"></line></svg></button><button class="tool-btn zoom-out" title="缩小画布" aria-label="缩小画布"><svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="8"></circle><line x1="21" y1="21" x2="16.65" y2="16.65"></line><line x1="8" y1="11" x2="14" y2="11"></line></svg></button><button class="tool-btn reset-view" title="重置位置与比例 (100%)" aria-label="重置位置与比例"><svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8"></path><path d="M3 3v5h5"></path></svg></button><button class="tool-btn fullscreen-toggle" title="全屏查看画布" aria-label="全屏查看画布"><svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="15 3 21 3 21 9"></polyline><polyline points="9 21 3 21 3 15"></polyline><line x1="21" y1="3" x2="14" y2="10"></line><line x1="3" y1="21" x2="10" y2="14"></line></svg></button></div></div></div><div class="diagram-viewport" title="按住拖拽平移画布，悬浮右上角调节缩放"><div class="diagram-stage"><div class="stage-dynamic-layer"><div class="mermaid" data-source="">flowchart LR A[本地编辑与撰写] --&gt;|git push origin main| B[私有仓库 blog-source] B --&gt;|GitHub Actions 触发| C[远程环境自动化编译打包] C --&gt;|静态产物推送| D[公开仓库 dorian7alden.github.io] D --&gt;|GitHub Pages CDN| E[全球访客流畅浏览]</div></div></div></div></div><p>双仓库流水线的设计收益体现在三个维度：</p><ul><li><strong>私有源码绝对安全</strong>：源码仓库保持私有属性，未完稿的草稿箱、自动化配置细节、私有笔记均不对外暴露。</li><li><strong>公开仓库仅含静态产物</strong>：目标公开仓库只接收 VitePress 编译生成的纯静态 HTML 文件，不包含任何敏感配置或源代码逻辑。</li><li><strong>全自动跨仓库部署流</strong>：通过在私有仓库配置 GitHub Personal Access Token，触发远程 CI/CD 自动化拉取、安装依赖、生产打包并强推至公开仓库，创作者本地无需执行繁琐的发布命令。</li></ul><h2 id="_4-协同规范与用户配置保护" tabindex="-1">4. 协同规范与用户配置保护 <a class="header-anchor" href="#_4-协同规范与用户配置保护" aria-label="Permalink to &quot;4. 协同规范与用户配置保护&quot;">​</a></h2><p>博主会随时根据个人偏好对排版边距、颜色变量、对齐微调等细节进行就地修改。在代码演进中，必须严格贯彻尊重用户手动调整的协作红线：</p><ul><li><strong>严禁随意覆盖或重置</strong>：修改代码或优化组件时，必须仔细识别并保留用户已调整的样式数值与排版参数。</li><li><strong>协同适配优于推翻重来</strong>：遇到设计冲突或实现重叠时，主动融合适配已有改动，而非通过强制重置抹去个人心血。</li><li><strong>持续验证构建产物</strong>：任何改动完成后，均须通过本地开发服务与生产构建命令双重验证，确保构建零报错、页面无坏链。</li></ul>`,19)])])}const h=a(t,[["render",l]]);export{u as __pageData,h as default};
